      const x = toNum(evaluate(e.x))
      if (x.t === 'err') return x
      return num(e.op === '-' ? -x.v : x.v)
    }
    case 'bin': {
      const l = evaluate(e.l)
      const r = evaluate(e.r)
      if (['=', '<>', '<', '<=', '>', '>='].includes(e.op)) {
