      }
      const a = toNum(l)
      if (a.t === 'err') return a
      const b = toNum(r)
      if (b.t === 'err') return b
      switch (e.op) {
        case '+': return finite(a.v + b.v)
        case '-': return finite(a.v - b.v)
        case '*': return finite(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
        case '^': return finite(Math.pow(a.v, b.v))
      }
      return err('#ERR!')
    }
    case 'call': return callFn(e)
  }
  return err('#ERR!')
