function callFn(e) {
  const { name, args } = e
  const n = args.length
  if (name === 'IF') {
    if (n !== 3) return err('#ERR!')
    const c = scalarArg(args[0])
    if (c.t === 'err') return c
    let truth
    if (c.t === 'bool') truth = c.v
    else if (c.t === 'num') truth = c.v !== 0
    else return err('#VALUE!')
    return scalarArg(truth ? args[1] : args[2])
  }
  if (name === 'ABS') {
    if (n !== 1) return err('#ERR!')
    const v = toNum(scalarArg(args[0]))
    if (v.t === 'err') return v
    return num(Math.abs(v.v))
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
  if (n < 1) return err('#ERR!')
  const vals = args.flatMap(argValues)
  const bad = vals.find((v) => v.t === 'err')
  if (bad) return bad
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'err') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return finite(Math.min(...nums))
    case 'MAX': return finite(Math.max(...nums))
    case 'AVG': return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
  }
}

// ---- output ----
function show(v) {
  switch (v.t) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

let out = ''
for (const cell of sorted) {
  const name = addrName(cell.a)
  if (mode[0] === 'values') {
    out += `${name}=${show(evalCell(cell.a))}\n`
  } else {
    const set = new Map()
    if (cell.parsed) collectDeps(cell.parsed, set)
    const list = [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row)
    out += `${name}:${list.map((a) => ' ' + addrName(a)).join('')}\n`
  }
}
process.stdout.write(out)
