function parseAddr(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1
    ? L.charCodeAt(0) - 64
    : 26 + (L.charCodeAt(0) - 65) * 26 + (L.charCodeAt(1) - 64)
