  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const fail = () => { throw new Error('parse') }
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { n: 'un', op, x: unary() }
    }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) fail()
    if (t.k === 'num') { p++; return { n: 'num', v: t.v } }
