  const bad = vals.find((v) => v.t === 'err')
  if (bad) return bad
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'err') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return finite(nums.reduce((m, x) => (x < m ? x : m), nums[0]))
    case 'MAX': return finite(nums.reduce((m, x) => (x > m ? x : m), nums[0]))
    case 'AVG': return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
  }
